/* From Uiverse.io by JaydipPrajapati1910 - Tags: input, transparent, input effect , box-shadow */
.__UIV_SCOPE__ .input {
  max-width: 190px;
  border: none;
  outline: none;
  background: none;
  font-size: 18px;
  color: #222;
  padding: 15px 5px 10px 20px;
  box-shadow: inset 4px 4px 4px rgba(15, 15, 15, 0.315),4px 4px 4px rgba(28, 28, 28, 0.13);
  border-radius: 25px;
  background-clip: padding-box;
}

.__UIV_SCOPE__ .input:focus {
  padding-bottom: 10px;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #222;
  text-transform: uppercase;
  transition: all 0.3s ease;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: .3px;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  color: #999;
}
